```matlab
function fibSeq = fibonacciSequence(n)
    if n <= 0
        fibSeq = [];
    else
        fibSeq = zeros(1, n);
        fibSeq(1) = 1;
        if n > 1
            fibSeq(2) = 1;
            for i = 3:n
                fibSeq(i) = fibSeq(i-1) + fibSeq(i-2);
            end
        end
    end
end

sequence = fibonacciSequence(10);
disp(sequence);
