```matlab
N = 10; % Total prime numbers to find
primesFound = 0;
num = 2; % Starting number
primeSequence = zeros(1, N); % Preallocate for efficiency
while primesFound < N
    isPrime = true;
    for i = 2:sqrt(num)
        if mod(num, i) == 0
            isPrime = false;
            break;
        end
    end
    if isPrime
        primesFound = primesFound + 1;
        primeSequence(primesFound) = num;
    end
    num = num + 1;
end
disp(primeSequence);
```

