```matlab
N = 10; % Number of primes desired
primesFound = 0;
num = 2;
primeSeq = zeros(1, N);

while primesFound < N
    isPrime = true;
    for i = 2:sqrt(num)
        if mod(num, i) == 0
            isPrime = false;
            break;
        end
    end
    if isPrime
        primesFound = primesFound + 1;
        primeSeq(primesFound) = num;
    end
    num = num + 1;
end

disp(primeSeq);
```

