```cpp
#include <iostream>

bool isPrime(int n) {
    if (n <= 1) return false;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) return false;
    }
    return true;
}

int main() {
    int count = 0;
    for (int i = 2; count < 10; i++) {
        if (isPrime(i)) {
            std::cout << i;
            if(count < 9) {
                std::cout << ", ";
            }
            count++;
        }
    }
    return 0;
}
```

```cpp
#include <iostream>

int main() {
    int n1 = 0, n2 = 1, nextTerm = 0, n = 10;

    for (int i = 1; i <= n; ++i) {
        if(i == 1) {
            std::cout << n2 << ", ";
            continue;
        }
        nextTerm = n1 + n2;
        n1 = n2;
        n2 = nextTerm;

        std::cout << nextTerm;
        if(i != n) std::cout << ", ";
    }
    return 0;
}
