```cpp
#include<iostream>
#include<vector>

int factorial(int n) {
    return (n == 1 || n == 0) ? 1 : n * factorial(n - 1);
}

bool isFactorion(int n) {
    int sum = 0, original = n;
    while(n > 0) {
        sum += factorial(n % 10);
        n /= 10;
    }
    return sum == original;
}

int main() {
    std::vector<int> factorions;
    for(int i = 1; i < 100000; ++i) {
        if(isFactorion(i)) {
            factorions.push_back(i);
        }
    }
    for(int factorion : factorions) {
        std::cout << factorion << " ";
    }
    return 0;
}
```

