```cpp
#include<iostream>
using namespace std;

int main() {
    long long dp[10];
    dp[0] = 1; 
    for(int i = 1; i < 10; ++i) {
        dp[i] = 0;
        for(int j = 0; j < i; ++j) {
            dp[i] += dp[j] * dp[i-1-j];
        }
    }
    for(int i = 0; i < 10; ++i) {
        if(i > 0) cout << ", ";
        cout << dp[i];
    }
    return 0;
}
