```cpp
#include <iostream>
#include <string>

std::string countAndSay(int n) {
    if (n == 1) return "1";
    std::string previous = countAndSay(n - 1), result = "";
    int count = 1;
    for (int i = 0; i < previous.length(); i++) {
        if (i + 1 < previous.length() && previous[i] == previous[i + 1]) {
            count++;
        } else {
            result += std::to_string(count) + previous[i];
            count = 1;
        }
    }
    return result;
}

int main() {
    for (int i = 1; i <= 5; i++) {
        std::cout << countAndSay(i) << std::endl;
    }
    return 0;
}
