```cpp
#include <iostream>
#include <vector>

int factorial(int n) {
    if(n == 0 || n == 1) return 1;
    else return n * factorial(n - 1);
}

bool isCurious(int n) {
    int sum = 0, original = n;
    while(n > 0) {
        int digit = n % 10;
        sum += factorial(digit);
        n /= 10;
    }
    return sum == original;
}

int main() {
    for(int i = 1; i <= 40585; ++i) { // Upper bound given by problem
        if(isCurious(i)) std::cout << i << ", ";
    }
}
