```cpp
#include <iostream>
#include <vector>

int factorial(int n) {
    return (n == 1 || n == 0) ? 1 : factorial(n - 1) * n;
}

bool isSpecial(int num) {
    int sum = 0, originalNum = num;
    while (num > 0) {
        sum += factorial(num % 10);
        num /= 10;
    }
    return sum == originalNum;
}

int main() {
    std::vector<int> specialNumbers = {1, 2, 145, 40585};
    for (int num : specialNumbers) {
        if (isSpecial(num)) {
            std::cout << num << std::endl;
        }
    }
    return 0;
}
