```cpp
#include <iostream>
#include <vector>

bool isPrime(int n) {
    if (n <= 1) return false;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) return false;
    }
    return true;
}

int main() {
    std::vector<int> sequence = {3};
    int count = 1, number = 4;
    while (count < 8) {
        if (isPrime(number)) {
            int diff = number - sequence.back();
            if (isPrime(diff)) {
                sequence.push_back(number);
                count++;
            }
        }
        number++;
    }

    for (int num : sequence) {
        std::cout << num << " ";
    }
    return 0;
}
