int main() {
    int arr[] = {128, 151, 153, 217, 224, 332, 382, 400, 450, 478};
    for (int i = 0; i < 10; i++) {
        cout << arr[i];
        if (i != 9) {
            cout << ", ";
        }
    }
    return 0;
}
