```javascript
function generatePrimes(n) {
  const primes = [];
  for (let num = 2; primes.length < n; num++) {
    let isPrime = true;
    for (let i = 2; i <= Math.sqrt(num); i++) {
      if (num % i === 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) {
      primes.push(num);
    }
  }
  return primes;
}

console.log(generatePrimes(10));
```

```javascript
function fibonacciSequence(n) {
    const sequence = [1, 1];
    for(let i = 2; i < n; i++) {
        sequence[i] = sequence[i-1] + sequence[i-2];
    }
    return sequence;
}

console.log(fibonacciSequence(10));
```

