  let sequence = [1, 2, 4, 8, 16];
  for(let i = 5; i < n; i++) {
    if(i % 4 === 0) {
      sequence.push(sequence[i-1] + 15);
    } else if(i % 4 === 1) {
      sequence.push(sequence[i-1] + 7);
    } else if(i % 4 === 2) {
      sequence.push(sequence[i-1] + 10);
    } else {
      sequence.push(sequence[i-1] + 31);
    }
  }
  return sequence;
}

console.log(generateSequence(10));
