```javascript
function sequence(n) {
    if (n === 0) return 1;
    let result = 0;
    for (let i = 0; i < n; i++) {
        result += combination(n + i, i) * sequence(n - 1 - i);
    }
    return result;
}

function combination(n, k) {
    return factorial(n) / (factorial(k) * factorial(n - k));
}

function factorial(n) {
    if (n === 0 || n === 1) return 1;
    let result = 1;
    for (let i = 2; i <= n; i++) {
        result *= i;
    }
    return result;
}

for (let n = 0; n < 10; n++) {
    console.log(sequence(n));
}
```

