```javascript
function lookAndSay(n) {
  let result = ["1"];
  for (let i = 1; i < n; i++) {
    let current = result[i - 1];
    let temp = "";
    let count = 1;
    for (let j = 0; j < current.length; j++) {
      if (current[j] === current[j + 1]) {
        count++;
      } else {
        temp += count.toString() + current[j];
        count = 1;
      }
    }
    result.push(temp);
  }
  return result;
}

console.log(lookAndSay(5));
```

