```javascript
function lookAndSay(sequence, iterations) {
  for (let i = 0; i < iterations; i++) {
    let currentNum = sequence[sequence.length - 1];
    let result = '';
    let count = 1;
    for (let j = 1; j <= currentNum.length; j++) {
      if (currentNum[j] === currentNum[j - 1]) {
        count++;
      } else {
        result += count.toString() + currentNum[j - 1];
        count = 1;
      }
    }
    sequence.push(result);
  }
  return sequence;
}

console.log(lookAndSay(['1'], 4));
```

