```javascript
function getNextPrime(n) {
    while (true) {
        n += 1;
        let isPrime = true;
        for (let i = 2; i * i <= n; i++) {
            if (n % i === 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) return n;
    }
}

function generateSequence(length) {
    let sequence = [];
    let number = 2; // Start searching for primes from 3
    for (let i = 0; i < length; i++) {
        number = getNextPrime(number);
        if (i % 2 === 0) { // Add only for even indices
            sequence.push(number);
            number *= 2; // Double the number to ensure the next number added is odd
        }
    }
    return sequence;
}

console.log(generateSequence(8));
```

