```javascript
function generateSequence() {
    let sequence = [];
    let primes = [];
    for (let number = 2; sequence.length < 10; number++) {
        let isPrime = true;
        for (let prime of primes) {
            if (number % prime === 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            primes.push(number);
            if (primes.length > 1) {
                sequence.push(primes[primes.length - 1] + primes[primes.length - 2]);
            }
        }
    }
    return sequence;
}

console.log(generateSequence());
```

